<g fill="#caa46a" stroke="#3d2a16" stroke-width="0.3"><circle cx="-6" cy="-0.4" r="0.8"/><circle cx="-2" cy="-1.4" r="0.8"/><circle cx="2" cy="-1.4" r="0.8"/><circle cx="6" cy="-0.4" r="0.8"/></g>
